            NULL,
            379,
            67,
            '{"parser": "legacy-migration", "file_name": "oai מדריך למשתמש המתקדם.docx", "file_type": "docx", "legacyData": {"legacy_id": "db593f2b-e01a-4613-b36e-178b83b0d6a2", "external_id": null, "collection": "collection", "type": "chunk-data", "tags": "", "user_id": "bfc620870ac0                                                                                                                                                                                                                                                    ", "create_date": "2025-05-20T14:10:04.063Z", "link_to_file": "https://jeenfilesdevweu.blob.core.windows.net/jeendocs/857ca8ca4fc24d6afbf9ff5b74818b87/data/1747750161226-51687f6634937e75715c42851bb177e5", "excerptKeywords": "KEYWORDS: Advance Options, Submit, סטטוס ההעלאה, לשונית הData, העלאת קובץ"}}'::jsonb,
